; graphic2.asm -- chapter 21: the picture in Graphic II
; generated by gen21.py
        INCLUDE "msx.inc"
        OUTPUT "graphic2.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; The picture of figure 21.1 in this mode. The registers first, with the
; display off; then the whole VRAM filled with noise; then the mode's tables,
; and nothing else; then the display on.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; 16 KB, display off
        VDP_REG 0, $02          ; mode: M3 = 1, Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $FF          ; colours  $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; backdrop white (15)
        VRAM_WRITE $0000        ; every byte of the VRAM: noise, the
        ld hl, $0000            ; BIOS's first 16 KB
        ld c, VDP_DATA
        ld d, 64                ; 64 x 256 bytes
noise:  ld b, 0
        otir
        dec d
        jr nz, noise
        VRAM_WRITE $0000        ; 6144 bytes of $00
        ld bc, 6144
pat:    ld a, $00
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, pat
        VRAM_WRITE $2000        ; 6144 bytes of $1F
        ld bc, 6144
col:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, col
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
nam:    xor a
nam1:   out (VDP_DATA), a
        inc a
        jr nz, nam1
        djnz nam
        ld hl, label            ; the words: the BIOS's shapes in their cells
        call glyphs
        VRAM_WRITE $1B00        ; the sprite attribute table ends at once
        ld a, $D0
        out (VDP_DATA), a
        ld hl, blocks           ; the tables gen21.py worked out
        call write_blocks
shown:  VDP_REG 1, $C0          ; the display on
done:   jr done

; write_blocks: HL = a list of blocks, each the VRAM address (2 bytes) and the
; number of bytes (2 bytes, 0 ends the list), then the bytes. Display off.
write_blocks:
        ld e, (hl)
        inc hl
        ld d, (hl)
        inc hl
        ld c, (hl)
        inc hl
        ld b, (hl)
        inc hl
        ld a, b
        or c
        ret z
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a
.byte:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .byte
        jr write_blocks

; glyphs: HL = a count, then for each character the VRAM address of its eight
; pattern bytes (2 bytes) and its code (1 byte): its shape from the BIOS's set.
glyphs: ld b, (hl)
        inc hl
.next:  push bc
        ld e, (hl)
        inc hl
        ld d, (hl)
        inc hl
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a
        ld a, (hl)              ; the code: its shape is at CGTABL + 8 x code
        inc hl
        push hl
        ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        ld de, (CGTABL)
        add hl, de
        ld b, 8
.byte:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .byte
        pop hl
        pop bc
        djnz .next
        ret
